import java.util.Scanner;

public class Main {
    static final int MAXNODES = 510;
    static int M, N, MOD;
    static int[] fact = new int[MAXNODES], inv_fact = new int[MAXNODES], invs = new int[MAXNODES];
    static int[] f_array = new int[MAXNODES], g_array = new int[MAXNODES], prefix_sum = new int[MAXNODES];
    static int[][] f_table = new int[MAXNODES][MAXNODES], g_table = new int[MAXNODES][MAXNODES];

    static int add_mod(int a, int b) {
        return (a + b) % MOD;
    }

    static int subtract_mod(int a, int b) {
        return a - b < 0 ? a - b + MOD : a - b;
    }

    static int multiply_mod(int a, int b) {
        return (int)((long)a * b % MOD);
    }

    static void precompute(int limit) {
        fact[0] = 1; invs[1] = 1; fact[1] = 1; inv_fact[0] = 1; inv_fact[1] = 1;
        for (int i = 2; i <= limit; i++) {
            invs[i] = multiply_mod((MOD - MOD / i), invs[MOD % i]);
        }
        for (int i = 2; i <= limit; i++) {
            fact[i] = multiply_mod(fact[i - 1], i);
            inv_fact[i] = multiply_mod(inv_fact[i - 1], invs[i]);
        }
    }

    static int choose(int n, int r) {
        if (n < r || r < 0) return 0;
        return multiply_mod(multiply_mod(fact[n], inv_fact[r]), inv_fact[n - r]);
    }

    static int arrangements(int n, int r) {
        return choose(n + r - 1, r - 1);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        N = sc.nextInt();
        M = sc.nextInt();
        MOD = sc.nextInt();

        precompute(500);

        for (int i = 1; i <= N; i++) {
            prefix_sum[i] = add_mod(prefix_sum[i - 1], i);
        }

        f_array[0] = 1;
        f_array[1] = 2;
        g_array[0] = 0;
        g_array[1] = 0;

        for (int i = 2; i <= N; i++) {
            for (int j = 0; j < i; j++) {
                int temp_val = multiply_mod(choose(i - 1, j), multiply_mod(f_array[j], f_array[i - 1 - j]));
                f_array[i] = add_mod(f_array[i], multiply_mod(temp_val, i + 1));
                g_array[i] = add_mod(g_array[i], multiply_mod(temp_val, add_mod(prefix_sum[j], prefix_sum[i - 1 - j])));
                int temp2 = multiply_mod(add_mod(multiply_mod(g_array[j], f_array[i - 1 - j]), multiply_mod(g_array[i - 1 - j], f_array[j])), i + 1);
                g_array[i] = add_mod(g_array[i], multiply_mod(temp2, choose(i - 1, j)));
            }
        }

        f_table[0][0] = 1;
        g_table[0][0] = 0;

        for (int i = 0; i <= M; i++) {
            for (int j = 0; j <= M; j++) {
                if (f_table[i][j] == 0) continue;
                for (int k = 1; k + j <= M; k++) {
                    f_table[i + 1][j + k] = add_mod(f_table[i + 1][j + k], multiply_mod(multiply_mod(f_table[i][j], f_array[k]), choose(j + k, k)));
                    g_table[i + 1][j + k] = add_mod(g_table[i + 1][j + k], multiply_mod(add_mod(multiply_mod(g_table[i][j], f_array[k]), multiply_mod(f_table[i][j], g_array[k])), choose(j + k, k)));
                }
            }
        }

        int final_ans = 0;
        for (int i = 1; i <= M; i++) {
            if (N + 1 - M >= i) {
                final_ans = add_mod(final_ans, multiply_mod(g_table[i][M], arrangements(N + 1 - M - i, i + 1)));
            }
        }

        System.out.println(final_ans);
        sc.close();
    }
}
